// oauth2Scopes returns the scopes an operation asks a scheme for. Without a
// selected security alternative, the first alternative naming the scheme applies.
func oauth2Scopes(operationID string, name string, requirementIndex int) []string {
	alternatives := oauth2OperationScopes[operationID]
	if requirementIndex >= 0 && requirementIndex < len(alternatives) {
		return alternatives[requirementIndex][name]
	}
	for _, alternative := range alternatives {
		if scopes, ok := alternative[name]; ok {
			return scopes
		}
	}
	return nil
}

func oauth2ProviderError(operationID string, request OAuth2TokenRequest, summary string, cause error) error {
	return &SdkAuthProviderError{
		OperationID: operationID,
		Preference:  "oauth2",
		Scheme:      request.Scheme,
		Scopes:      request.Scopes,
		Message:     "auth oauth2 " + summary + " for operation " + operationID,
		Cause:       cause,
	}
}

// oauth2Flight is one token request in flight: concurrent requests that find
// the same token missing or expired wait on done and share its result.
type oauth2Flight struct {
	done  chan struct{}
	token OAuth2Token
	err   error
}

// oauth2FlightKey names a token by the value that owns it and its key there.
type oauth2FlightKey struct {
	owner any
	key   string
}

var (
	oauth2Flights   = map[oauth2FlightKey]*oauth2Flight{}
	oauth2FlightsMu sync.Mutex
)

// singleFlightOAuth2 runs fetch once for concurrent callers asking for the
// same token; every caller receives that one result or error.
func singleFlightOAuth2(ctx context.Context, id oauth2FlightKey, fetch func() (OAuth2Token, error)) (OAuth2Token, error) {
	oauth2FlightsMu.Lock()
	if flight, ok := oauth2Flights[id]; ok {
		oauth2FlightsMu.Unlock()
		select {
		case <-flight.done:
			return flight.token, flight.err
		case <-ctx.Done():
			return OAuth2Token{}, ctx.Err()
		}
	}
	flight := &oauth2Flight{done: make(chan struct{})}
	oauth2Flights[id] = flight
	oauth2FlightsMu.Unlock()

	defer func() {
		oauth2FlightsMu.Lock()
		delete(oauth2Flights, id)
		oauth2FlightsMu.Unlock()
		close(flight.done)
	}()
	flight.token, flight.err = fetch()
	return flight.token, flight.err
}

// applyOAuth2Provider attaches the provider's access token to one request.
// The requested scopes never leave the provider call, and the token reaches
// the wire only as an Authorization header.
func applyOAuth2Provider(ctx context.Context, cfg *ClientConfig, provider OAuth2TokenProvider, headers map[string]string, name string, operationID string, requirementIndex int) error {
	request := OAuth2TokenRequest{
		Scheme:     name,
		TokenURL:   oauth2TokenURLs[name],
		RefreshURL: oauth2RefreshURLs[name],
		Scopes:     oauth2Scopes(operationID, name, requirementIndex),
	}
	if provider == nil {
		return oauth2ProviderError(operationID, request, "requires a configured OAuth 2 token provider", nil)
	}

	token, err := provider.GetAccessToken(ctx, request)
	if err != nil {
		return oauth2ProviderError(operationID, request, "could not obtain an access token", err)
	}
	if !token.Usable() {
		// The declared refresh integration point: an expired or invalid token
		// goes back to the provider before the request is dispatched. Requests
		// share one refresh per provider; a provider of an incomparable type
		// cannot be a map key, so its requests share one only per config.
		var owner any = cfg
		if reflect.TypeOf(provider).Comparable() {
			owner = provider
		}
		id := oauth2FlightKey{owner, oauth2CacheKey(name, request.Scopes)}
		token, err = singleFlightOAuth2(ctx, id, func() (OAuth2Token, error) {
			return provider.RefreshAccessToken(ctx, request)
		})
		if err != nil {
			return oauth2ProviderError(operationID, request, "could not refresh the expired access token", err)
		}
		if !token.Usable() {
			return oauth2ProviderError(operationID, request, "obtained no usable access token", nil)
		}
	}
	headers["Authorization"] = "Bearer " + token.AccessToken
	return nil
}

// oauth2CacheKey identifies one scheme or token endpoint and scope set. Scopes
// are sorted so two requirements that ask for the same access share a token.
func oauth2CacheKey(source string, scopes []string) string {
	sorted := append([]string(nil), scopes...)
	sort.Strings(sorted)
	return source + "|" + strings.Join(sorted, " ")
}

// oauth2TokenPayload is the token-endpoint response fields the SDK reads.
type oauth2TokenPayload struct {
	AccessToken  string `json:"access_token"`
	ExpiresIn    int    `json:"expires_in"`
	RefreshToken string `json:"refresh_token"`
}

// expiresAt is when the issued token expires, one hour out when the endpoint
// does not say.
func (p oauth2TokenPayload) expiresAt() time.Time {
	ttl := time.Duration(p.ExpiresIn) * time.Second
	if ttl <= 0 {
		ttl = time.Hour
	}
	return time.Now().Add(ttl)
}

// postOAuth2Form POSTs a token-endpoint form and decodes the JSON response.
// A rejected request returns an *SdkHttpError carrying the endpoint's body.
func postOAuth2Form(ctx context.Context, tokenURL string, form url.Values) (oauth2TokenPayload, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, tokenURL, strings.NewReader(form.Encode()))
	if err != nil {
		return oauth2TokenPayload{}, err
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	req.Header.Set("Accept", "application/json")

	resp, err := httpClient.Do(req)
	if err != nil {
		return oauth2TokenPayload{}, err
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return oauth2TokenPayload{}, err
	}
	if resp.StatusCode >= 400 {
		headers := flattenHeaders(resp.Header)
		return oauth2TokenPayload{}, &SdkHttpError{
			StatusCode: resp.StatusCode,
			StatusText: http.StatusText(resp.StatusCode),
			Body:       body,
			Headers:    headers,
			RequestID:  findRequestID(headers),
		}
	}
	var payload oauth2TokenPayload
	if err := json.Unmarshal(body, &payload); err != nil {
		return oauth2TokenPayload{}, err
	}
	return payload, nil
}

// OAuth2RefreshTokenProvider is the built-in provider for the refresh-token
// grant: it refreshes the access token before it expires and adopts each
// refresh token the server rotates in, passing it to OnRefreshTokenRotated so
// it can be persisted. Create it with NewOAuth2RefreshTokenProvider.
type OAuth2RefreshTokenProvider struct {
	ClientID     string
	ClientSecret string
	// RefreshURL overrides the request's RefreshURL.
	RefreshURL string
	// OnRefreshTokenRotated receives each refresh token the server rotates in.
	OnRefreshTokenRotated func(refreshToken string)

	mu           sync.Mutex
	refreshToken string
	token        OAuth2Token
}

// NewOAuth2RefreshTokenProvider returns a provider that starts from
// refreshToken; its first request runs the refresh-token grant.
func NewOAuth2RefreshTokenProvider(refreshToken string) *OAuth2RefreshTokenProvider {
	return &OAuth2RefreshTokenProvider{refreshToken: refreshToken}
}

func (p *OAuth2RefreshTokenProvider) GetAccessToken(ctx context.Context, request OAuth2TokenRequest) (OAuth2Token, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.token, nil
}

func (p *OAuth2RefreshTokenProvider) RefreshAccessToken(ctx context.Context, request OAuth2TokenRequest) (OAuth2Token, error) {
	p.mu.Lock()
	defer p.mu.Unlock()

	form := url.Values{}
	form.Set("grant_type", "refresh_token")
	form.Set("refresh_token", p.refreshToken)
	if p.ClientID != "" {
		form.Set("client_id", p.ClientID)
	}
	if p.ClientSecret != "" {
		form.Set("client_secret", p.ClientSecret)
	}
	refreshURL := p.RefreshURL
	if refreshURL == "" {
		refreshURL = request.RefreshURL
	}
	payload, err := postOAuth2Form(ctx, refreshURL, form)
	if err != nil {
		return OAuth2Token{}, err
	}
	p.token = OAuth2Token{AccessToken: payload.AccessToken, ExpiresAt: payload.expiresAt()}
	if payload.RefreshToken != "" && payload.RefreshToken != p.refreshToken {
		p.refreshToken = payload.RefreshToken
		if p.OnRefreshTokenRotated != nil {
			p.OnRefreshTokenRotated(payload.RefreshToken)
		}
	}
	return p.token, nil
}

// OAuth2PkcePair is a PKCE code verifier and the S256 challenge derived from
// it (RFC 7636).
type OAuth2PkcePair struct {
	Verifier  string
	Challenge string
	Method    string
}

// NewPkcePair creates a PKCE verifier and its S256 challenge. Keep the
// verifier with the login attempt until its authorization code is exchanged.
func NewPkcePair() (OAuth2PkcePair, error) {
	random := make([]byte, 32)
	if _, err := rand.Read(random); err != nil {
		return OAuth2PkcePair{}, err
	}
	verifier := base64.RawURLEncoding.EncodeToString(random)
	digest := sha256.Sum256([]byte(verifier))
	return OAuth2PkcePair{
		Verifier:  verifier,
		Challenge: base64.RawURLEncoding.EncodeToString(digest[:]),
		Method:    "S256",
	}, nil
}

// OAuth2AuthorizationURLOptions is the authorization request the application
// sends the user to.
type OAuth2AuthorizationURLOptions struct {
	ClientID      string
	RedirectURI   string
	CodeChallenge string
	Scopes        []string
	State         string
	// AuthorizationURL overrides the spec's authorizationUrl.
	AuthorizationURL string
}

// BuildAuthorizationURL returns the authorization-code URL to send the user
// to. The application owns the browser, the redirect, and checking State when
// the user comes back.
func BuildAuthorizationURL(options OAuth2AuthorizationURLOptions) (string, error) {
	base := options.AuthorizationURL
	if base == "" {
		base = "https://api.vercel.com/oauth/authorize"
	}
	target, err := url.Parse(base)
	if err != nil {
		return "", err
	}
	query := target.Query()
	query.Set("response_type", "code")
	query.Set("client_id", options.ClientID)
	query.Set("redirect_uri", options.RedirectURI)
	query.Set("code_challenge", options.CodeChallenge)
	query.Set("code_challenge_method", "S256")
	if len(options.Scopes) > 0 {
		query.Set("scope", strings.Join(options.Scopes, " "))
	}
	if options.State != "" {
		query.Set("state", options.State)
	}
	target.RawQuery = query.Encode()
	return target.String(), nil
}

// OAuth2AuthorizationCodeExchange is the token request that redeems an
// authorization code.
type OAuth2AuthorizationCodeExchange struct {
	Code         string
	CodeVerifier string
	RedirectURI  string
	ClientID     string
	ClientSecret string
	// TokenURL overrides the spec's tokenUrl.
	TokenURL string
}

// OAuth2AuthorizationCodeTokens is what a code is redeemed for; persist
// RefreshToken to renew access without another login.
type OAuth2AuthorizationCodeTokens struct {
	AccessToken  string
	ExpiresAt    time.Time
	RefreshToken string
}

// ExchangeAuthorizationCode redeems an authorization code and its PKCE
// verifier at the token endpoint.
func ExchangeAuthorizationCode(ctx context.Context, exchange OAuth2AuthorizationCodeExchange) (OAuth2AuthorizationCodeTokens, error) {
	form := url.Values{}
	form.Set("grant_type", "authorization_code")
	form.Set("code", exchange.Code)
	form.Set("redirect_uri", exchange.RedirectURI)
	form.Set("client_id", exchange.ClientID)
	form.Set("code_verifier", exchange.CodeVerifier)
	if exchange.ClientSecret != "" {
		form.Set("client_secret", exchange.ClientSecret)
	}
	tokenURL := exchange.TokenURL
	if tokenURL == "" {
		tokenURL = "https://api.vercel.com/oauth/access_token"
	}

	payload, err := postOAuth2Form(ctx, tokenURL, form)
	if err != nil {
		return OAuth2AuthorizationCodeTokens{}, err
	}
	if payload.AccessToken == "" {
		return OAuth2AuthorizationCodeTokens{}, fmt.Errorf("oauth2: token response missing access_token")
	}
	return OAuth2AuthorizationCodeTokens{
		AccessToken:  payload.AccessToken,
		ExpiresAt:    payload.expiresAt(),
		RefreshToken: payload.RefreshToken,
	}, nil
}

// OAuth2Auth holds an OAuth 2 credential. Set AccessToken to attach a
// pre-acquired token verbatim, set ClientID/ClientSecret to have the SDK
// auto-fetch tokens via the clientCredentials flow, or set Provider to supply
// tokens from any other flow the application runs.
type OAuth2Auth struct {
	AccessToken  string
	ClientID     string
	ClientSecret string
	TokenURL     string
	Scopes       []string
	Provider     OAuth2TokenProvider
}

type oauth2CacheEntry struct {
	accessToken string
	expiresAt   time.Time
}

var (
	oauth2Cache   = map[string]oauth2CacheEntry{}
	oauth2CacheMu sync.Mutex
)

func resolveOAuth2Token(ctx context.Context, auth *OAuth2Auth, defaultTokenURL string) (string, error) {
	if auth.AccessToken != "" {
		return auth.AccessToken, nil
	}
	tokenURL := auth.TokenURL
	if tokenURL == "" {
		tokenURL = defaultTokenURL
	}
	if tokenURL == "" {
		return "", fmt.Errorf("oauth2: tokenUrl is required for client credentials flow")
	}

	sortedScopes := append([]string(nil), auth.Scopes...)
	sort.Strings(sortedScopes)
	cacheKey := auth.ClientID + "|" + tokenURL + "|" + strings.Join(sortedScopes, ",")

	oauth2CacheMu.Lock()
	if entry, ok := oauth2Cache[cacheKey]; ok && time.Now().Add(oauth2ExpirySkew).Before(entry.expiresAt) {
		oauth2CacheMu.Unlock()
		return entry.accessToken, nil
	}
	oauth2CacheMu.Unlock()

	token, err := singleFlightOAuth2(ctx, oauth2FlightKey{key: cacheKey}, func() (OAuth2Token, error) {
		return exchangeOAuth2ClientCredentials(ctx, auth, tokenURL, cacheKey)
	})
	return token.AccessToken, err
}

// exchangeOAuth2ClientCredentials runs the client-credentials grant and caches
// the issued token under cacheKey.
func exchangeOAuth2ClientCredentials(ctx context.Context, auth *OAuth2Auth, tokenURL string, cacheKey string) (OAuth2Token, error) {
	form := url.Values{}
	form.Set("grant_type", "client_credentials")
	form.Set("client_id", auth.ClientID)
	form.Set("client_secret", auth.ClientSecret)
	if len(auth.Scopes) > 0 {
		form.Set("scope", strings.Join(auth.Scopes, " "))
	}

	payload, err := postOAuth2Form(ctx, tokenURL, form)
	if err != nil {
		return OAuth2Token{}, err
	}
	if payload.AccessToken == "" {
		return OAuth2Token{}, fmt.Errorf("oauth2: token response missing access_token")
	}

	token := OAuth2Token{AccessToken: payload.AccessToken, ExpiresAt: payload.expiresAt()}
	oauth2CacheMu.Lock()
	oauth2Cache[cacheKey] = oauth2CacheEntry{accessToken: token.AccessToken, expiresAt: token.ExpiresAt}
	oauth2CacheMu.Unlock()
	return token, nil
}

// applyAuthScheme attaches one named scheme. Schema-wide credential branches
// skip absent optional values; selection-owned providers return typed failures
// when the operation cannot obtain the credential it requires.
func applyAuthScheme(ctx context.Context, cfg *ClientConfig, headers map[string]string, query map[string]any, name string, operationID string) error {
	switch name {
	case "bearerToken":
		if cfg == nil || cfg.Auth == nil {
			return nil
		}
		if cfg.Auth.BearerToken != "" {
			headers["Authorization"] = "Bearer " + cfg.Auth.BearerToken
		}
	case "oauth2":
		if cfg == nil || cfg.Auth == nil {
			return nil
		}
		if cfg.Auth.Oauth2 != nil {
			if cfg.Auth.Oauth2.Provider != nil {
				return applyOAuth2Provider(ctx, cfg, cfg.Auth.Oauth2.Provider, headers, name, operationID, -1)
			}
			token, err := resolveOAuth2Token(ctx, cfg.Auth.Oauth2, "https://api.vercel.com/oauth/access_token")
			if err != nil {
				return err
			}
			headers["Authorization"] = "Bearer " + token
		}
	}
	return nil
}

// applyAuth attaches credentials to the outgoing request. Selection-aware
// modes validate the current operation before applying any scheme.
func applyAuth(ctx context.Context, cfg *ClientConfig, headers map[string]string, query map[string]any, operationID string) error {

	if cfg == nil || cfg.Auth == nil {
		return nil
	}

	if err := applyAuthScheme(ctx, cfg, headers, query, "bearerToken", operationID); err != nil {
		return err
	}
	if err := applyAuthScheme(ctx, cfg, headers, query, "oauth2", operationID); err != nil {
		return err
	}
	return nil

}
